// Unverified leads (#660): offers the offer-hunter spotted on X, Reddit or
// the web but could not confirm on an official page. Generated by
// scripts/load-leads.mjs into src/data/unverified.json — a separate artifact
// from offers.json, so leads never reach the listing, search, index.json,
// llms files or offer pages.

export type LeadReason =
  | "bot_walled"
  | "official_silent"
  | "no_amount"
  | "single_source"
  | "other";

export interface LeadSource {
  url: string;
  type: "x" | "reddit" | "web";
  author: string | null;
  handle: string | null;
  date: string | null;
}

export interface Lead {
  slug: string;
  provider: string;
  title: string;
  claim: string;
  amount_claimed: string | null;
  sources: LeadSource[];
  /** Newest dated source post (YYYY-MM-DD); the lead is listed for 3 days after it. */
  posted: string;
  first_seen: string;
  last_seen: string;
  reason: LeadReason;
  reason_detail: string;
  /** Official pages the hunt checked (validated to the provider's own hosts). */
  official_urls_tried?: string[];
}

export interface LeadsIndex {
  generated_at: string;
  count: number;
  leads: Lead[];
}

export const EMPTY_LEADS: LeadsIndex = {
  generated_at: "",
  count: 0,
  leads: [],
};

/** Plain-words label for why a lead could not be verified. */
export const REASON_LABELS: Record<LeadReason, string> = {
  bot_walled: "Official pages could not be read",
  official_silent: "Official pages say nothing about it",
  no_amount: "No amount stated officially",
  single_source: "Only one source",
  other: "Could not be verified",
};

/** Visible label for a source link: "@handle on X", "Reddit post", host. */
export function sourceLabel(source: LeadSource): string {
  if (source.type === "x") {
    return source.handle ? `${source.handle} on X` : "Post on X";
  }
  if (source.type === "reddit") return "Reddit post";
  try {
    return new URL(source.url).hostname.replace(/^www\./, "");
  } catch {
    return "Web page";
  }
}

/** Relative href of a lead's own page (#660), from a root-level document. */
export function leadHref(slug: string): string {
  return `unverified/${slug}.html`;
}
